<?php
declare(strict_types=1);require_once __DIR__.'/../config/api.php';if($_SERVER['REQUEST_METHOD']!=='GET')respond(['success'=>false,'message'=>'Method not allowed'],405);$u=requireUser($pdo);$status=trim((string)($_GET['status']??''));$where='j.user_id=?';$params=[$u['user_id']];if($status!==''){$where.=' AND j.status=?';$params[]=$status;}$s=$pdo->prepare("SELECT j.id job_id,j.status,j.assigned_at,j.start_date,j.end_date,j.payout_amount,j.completed_at,v.id vacancy_id,v.title,h.id hotel_id,h.name hotel_name,h.address_line,h.city,h.state,c.name category_name,r.name job_role_name FROM jobs j INNER JOIN vacancies v ON v.id=j.vacancy_id INNER JOIN hotels h ON h.id=j.hotel_id INNER JOIN categories c ON c.id=v.category_id INNER JOIN job_roles r ON r.id=v.job_role_id WHERE $where ORDER BY j.start_date DESC,j.created_at DESC");$s->execute($params);respond(['success'=>true,'data'=>$s->fetchAll(PDO::FETCH_ASSOC)]);
